    expect(formats, 'запрошенные типы').toEqual(expect.arrayContaining(['ean_13', 'ean_8', 'upc_a', 'code_128']));
    for (const f of ['itf', 'codabar', 'code_39', 'code_93', 'qr_code']) expect(formats, `тип ${f} не принимается`).not.toContain(f);

    await feed(page, '5710840209437');
    await expect(dlg, 'одно чтение — код не принят').toBeVisible();
    await expect(skuField(page)).toHaveValue('');
    await feed(page, '96385074', '5710840209437', '96385074');
